 {k:'tl',p:'Fransız İhtilali ve Osmanlı’daki yenilikleri sırala.',ev:[[1789,'Bastille baskını'],[1839,'Tanzimat Fermanı'],[1856,'Islahat Fermanı'],[1876,'Meclis-i Mebusan açıldı']],mis:'u3_tarih',e:'İhtilalin yaydığı fikirlerden sonra Osmanlı 1839, 1856 ve 1876’da önemli adımlar attı.'},
 {k:'sort',p:'Maddeleri ait oldukları akıma yerleştir.',bins:['Rönesans','Reform','Aydınlanma'],items:[['İtalya’da başladı',0],['Hümanizm yayıldı',0],['Martin Luther',1],['Endüljansa tepki',1],['Newton ve Kant',2],['İhtilale zemin hazırladı',2]],mis:'u3_akim',e:'Rönesans sanat ve bilim, Reform din, Aydınlanma akıl ve deney çağıdır.'},
 {k:'mc',p:'Endüljans nedir?',a:'Günahların bağışlanması için para karşılığı verilen belge',w:[['Kişinin dinden çıkarılması','u3_akim'],['Bir bölge halkının dinî haklardan mahrum edilmesi','u3_akim']],e:'Dinden çıkarma aforoz, bölgenin dinî haklardan mahrum edilmesi enterdidir.'},
 {k:'mc',p:'Reform hareketleri nerede ve kimin öncülüğünde başlamıştır?',a:'Almanya’da, Martin Luther öncülüğünde',w:[['İtalya’da, Leonardo da Vinci öncülüğünde','u3_akim'],['Fransa’da, XVI. Louis öncülüğünde','u3_akim']],e:'Luther 1517’de bildirisini Wittenberg Kilisesi’nin kapısına asmıştır.'},
 {k:'tf',p:'Reform hareketleri Osmanlı Devleti’ni doğrudan etkilememiş; Osmanlı’daki gayrimüslimler inançlarını özgürce yaşamıştır.',a:true,mis:'u3_neden',e:'Osmanlı farklı din ve mezheplerin barış içinde yaşamasına önem vermiştir.'},
 {k:'mc',p:'Avrupa’daki mezhep savaşlarının Osmanlı’ya etkisi ne olmuştur?',a:'Yeni bir Haçlı birliğini bir süre engelleyip ilerlemeyi kolaylaştırdı',w:[['Osmanlı’da mezhep savaşları başlattı','u3_neden'],['Avrupa’nın siyasi birliğini güçlendirdi','u3_neden']],e:'Avrupa’nın siyasi birliği zayıflayınca Osmanlı’ya karşı yeni bir Haçlı birliği kurulamadı.'},
 {k:'mc',p:'Aydınlanma Çağı’nda doğru bilgiye nasıl ulaşılacağı savunulmuştur?',a:'Akıl, gözlem ve deney yoluyla',w:[['Yalnızca kilisenin sözüyle','u3_akim'],['Yalnızca geleneklerle','u3_akim']],e:'Bu dönemde bilimsel yöntem önem kazanmıştır.'},
 {k:'order',p:'Avrupa’daki gelişmeleri ortaya çıkış sırasına göre düzenle.',items:['Rönesans','Reform','Aydınlanma Çağı','Fransız İhtilali'],mis:'u3_tarih',e:'Rönesans 14. yüzyılda, Reform 16. yüzyılda başladı; Aydınlanma 17–18. yüzyıllarda, İhtilal 1789’da oldu.'},
 {k:'mc',p:'Sanayi İnkılabı nerede ve ne zaman başlamıştır?',a:'İngiltere’de, XVIII. yüzyılın ikinci yarısında',w:[['Fransa’da, 1789’da','u3_akim'],['Osmanlı’da, Lale Devri’nde','u3_donem']],e:'Sanayi İnkılabı İngiltere’de başlamış, sonra yayılmıştır.'},
 {k:'mc',p:'Sanayi İnkılabı’nda üretimi değiştiren önemli gelişme hangisidir?',a:'James Watt’ın buhar makinesini geliştirmesi',w:[['Matbaanın öğrenilmesi','u3_akim'],['Pusulanın kullanılması','u3_akim']],e:'Buhar makinesi önce fabrikalarda, sonra tren, gemi ve dokuma tezgâhlarında kullanıldı.'},
 {k:'sort',p:'Sanayi İnkılabı ile ilgili maddeleri neden ve sonuç olarak ayır.',bins:['Neden','Sonuç'],items:[['Bilimsel buluşlar',0],['Buhar makinesi',0],['Fabrikalar çoğaldı',1],['İşçi sınıfı doğdu',1],['Şehirlere göç arttı',1],['Ham madde ihtiyacı arttı',1]],mis:'u3_neden',e:'Buluşlar ve buhar makinesi nedendir; fabrikalar, göç ve ham madde ihtiyacı sonuçtur.'},
 {k:'src',src:{t:'belge',title:'Sanayi İnkılabı ve Osmanlı',by:'Ders kitabı metni',text:'Avrupa fabrikalarında makinelerle yapılan seri ve ucuz üretim, Osmanlı’daki el tezgâhlarını zor durumda bıraktı. Ucuz Avrupa malları yerli üretimi azalttı, birçok imalathane kapandı. İşsizlik arttı, ekonomi zayıfladı.'},p:'Kaynağa göre doğru neden-sonuç sırası hangisidir?',a:'Ucuz Avrupa malı → yerli üretim azaldı → işsizlik arttı',w:[['İşsizlik arttı → fabrikalar kuruldu → mal ucuzladı','u3_neden'],['Yerli üretim arttı → Avrupa malı azaldı','u3_kanit']],e:'Kaynak zinciri ucuz Avrupa malıyla başlatır ve ekonominin zayıflamasıyla bitirir.'},
 {k:'src',src:{t:'alinti',title:'Milliyetçilik ve Osmanlı',by:'Demir (2011)',text:'Fransız İhtilali’nin yaydığı milliyetçilik akımı, çok uluslu Osmanlı ülkesinde şiddetle hissedildi. Özellikle Balkanlardaki gayrimüslim toplulukları etkiledi. Osmanlı, milliyetçi iç isyanlarla karşılaştı; devletin dağılma süreci hızlandı.'},p:'Kaynağa göre milliyetçilik Osmanlı’yı neden bu kadar etkilemiştir?',a:'Osmanlı’da farklı milletler bir arada yaşıyordu',w:[['Osmanlı’da yalnızca tek bir millet vardı','u3_kanit'],['Osmanlı, Fransa’ya bağlı bir ülkeydi','other']],e:'“Çok uluslu” ifadesi, farklı milletlerin bir arada yaşadığını gösterir.'},
 {k:'src',src:{t:'gazete',title:'Bastille Düştü!',by:'Örnek tarih gazetesi (canlandırma)',date:'14 Temmuz 1789',text:'Paris’te halk bugün Bastille Hapishanesini ele geçirdi. Kral XVI. Louis’nin yeni vergi isteği halkı öfkelendirmişti. Bence bu, Avrupa’nın en heyecan verici günü!'},p:'Haberdeki hangi ifade bir görüştür?',a:'“Bence bu, Avrupa’nın en heyecan verici günü!”',w:[['“Halk Bastille Hapishanesini ele geçirdi.”','u3_kanit'],['“Kralın yeni vergi isteği halkı öfkelendirdi.”','u3_kanit']],e:'“Bence” ile başlayan cümle kişisel görüştür; diğerleri olayları aktarır.'},
 {k:'mc',p:'İnsan ve Yurttaş Hakları Bildirgesi ile hangi anlayış kabul edilmiştir?',a:'İnsanların özgür ve kanun önünde eşit olduğu',w:[['Soyluların vergi vermeyeceği','u3_neden'],['Kralın yetkisinin sınırsız olduğu','u3_neden']],e:'Bildirge ile insan hakları yasal güvence altına alınmıştır.'},
 {k:'mc',p:'Milliyetçilik akımı hangi anlayışla yayılmıştır?',a:'“Her millete bir devlet”',w:[['“Her krala bir ülke”','u3_akim'],['“Her şehre bir kilise”','u3_akim']],e:'Milliyetçilik ortak dil, kültür ve geçmişe sahip toplulukların kendi devletini kurmasını savunur.'},
 {k:'mc',p:'1856’da ilan edilen Islahat Fermanı ile ne sağlanmıştır?',a:'Gayrimüslimlere memur olabilme ve okul açabilme hakkı',w:[['Yeniçeri Ocağı’nın kaldırılması','u3_donem'],['İlk Türk matbaasının açılması','u3_donem']],e:'Yeniçeri Ocağı 1826’da kaldırıldı, ilk matbaa 1727’de açıldı.'},
 {k:'tf',p:'Fransız İhtilali öncesinde soylular ve din görevlileri vergi vermezken vergi yükü büyük ölçüde halkın üzerindeydi.',a:true,mis:'u3_neden',e:'Bu adaletsizlik, ihtilalin nedenlerinden biridir.'},
 {k:'sc',role:'Bir Osmanlı şehrinde dokumacı ustasısın. Pazara Avrupa’dan çok ucuz fabrika kumaşları gelmeye başladı.',steps:[
   {p:'Müşterilerin azaldı. Durumu nasıl yorumlarsın?',o:[['Ucuz malın makineyle seri üretildiğini anlarım',2,'Doğru neden: Avrupa fabrikalarında makineyle seri ve ucuz üretim yapılıyor.'],['Müşterilerim beni sevmiyor diye düşünürüm',0,'Gerçek neden kişisel değil, ekonomiktir: Sanayi İnkılabı.','u3_neden']]},
   {p:'Atölyeni ayakta tutmak için ne yaparsın?',o:[['Yeni teknikleri öğrenip kaliteli üretime odaklanırım',2,'Değişime uyum sağlamak ve yeni teknikleri öğrenmek en akıllıca yoldur.'],['Hiçbir şeyi değiştirmem',1,'Geleneğin değeri var ama değişimi görmezden gelmek birçok atölyenin kapanmasına yol açtı.'],['Atölyeyi hemen kapatırım',0,'Vazgeçmek işsizliği artırır; kitap bunun ekonomiyi zayıflattığını anlatır.','u3_neden']]}],
  e:'Sanayi İnkılabı Osmanlı’da el tezgâhlarını zorladı. Sorunun gerçek nedenini görmek, çözümün ilk adımıdır.'},
 {k:'map',map:'dunya',p:'Sanayi İnkılabı’nın başladığı ülkeyi haritada bul.',a:'GBR',w:['FRA','DEU','ITA'],mis:'u3_yon',e:'Sanayi İnkılabı İngiltere’de başlamıştır.'},
 {k:'map',map:'dunya',p:'Reform hareketlerinin ilk başladığı ülkeyi haritada bul.',a:'DEU',w:['ITA','FRA','ESP'],mis:'u3_yon',e:'Reform, Martin Luther öncülüğünde Almanya’da başlamıştır.'}
